-- Generated from the supplied ESO Arabic UI string tables.
-- Applies all SI strings in the add-on and can restore the original client strings.
local saved = ESOArabicSavedVariables or {}
ESOArabicSavedVariables = saved
if saved.legacyArabicStringRecoveryPending then return end
if type(SafeAddString) ~= "function" or type(GetString) ~= "function" then return end

local active = type(ESO_ARABIC_IS_ACTIVE) == "function" and ESO_ARABIC_IS_ACTIVE()
local originals = saved.originalClientStrings
if active then
    originals = originals or {}
    saved.originalClientStrings = originals
elseif type(originals) ~= "table" then
    return
end

local baseVersion = tonumber(saved.clientStringVersion) or 100
local restoreVersion = baseVersion + 2
local function apply(id, translated, key, translatedVersion)
    if not id then return end
    if active then
        if originals[key] == nil then originals[key] = GetString(id) end
        SafeAddString(id, translated, translatedVersion)
    elseif originals[key] ~= nil then
        SafeAddString(id, originals[key], restoreVersion)
    end
end
